INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk5-02','HSK5-02','HSK 5 · Đề 02','hsk','HSK 5',70,'published',1,'Đề luyện HSK 5 số 02 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk5-02-q01','seed-hsk5-02',1,'single_choice','Pinyin phù hợp với “沟通” là phương án nào?','Pinyin của “沟通” là “gōutōng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “giao tiếp”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-02-q02','seed-hsk5-02',2,'single_choice','Chọn từ Hán ngữ có nghĩa “xu hướng”.','Từ phù hợp là “趋势”, đọc là qūshì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-02-q03','seed-hsk5-02',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “观点 — guāndiǎn”, nghĩa là “quan điểm”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-02-q04','seed-hsk5-02',4,'single_choice','Từ “原则” gần nghĩa nhất với phương án nào?','“原则” (yuánzé) có nghĩa là “nguyên tắc”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 5.',NULL,NULL,0,1,'',datetime('now')),
