INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk5-04','HSK5-04','HSK 5 · Đề 04','hsk','HSK 5',70,'published',1,'Đề luyện HSK 5 số 04 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk5-04-q01','seed-hsk5-04',1,'single_choice','Pinyin phù hợp với “判断” là phương án nào?','Pinyin của “判断” là “pànduàn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “phán đoán”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-04-q02','seed-hsk5-04',2,'single_choice','Chọn từ Hán ngữ có nghĩa “thúc đẩy”.','Từ phù hợp là “促进”, đọc là cùjìn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-04-q03','seed-hsk5-04',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “沟通 — gōutōng”, nghĩa là “giao tiếp”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-04-q04','seed-hsk5-04',4,'single_choice','Từ “趋势” gần nghĩa nhất với phương án nào?','“趋势” (qūshì) có nghĩa là “xu hướng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 5.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-04-q05','seed-hsk5-04',5,'single_choice','Pinyin phù hợp với “观点” là phương án nào?','Pinyin của “观点” là “guāndiǎn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “quan điểm”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-04-q06','seed-hsk5-04',6,'single_choice','Chọn từ Hán ngữ có nghĩa “nguyên tắc”.','Từ phù hợp là “原则”, đọc là yuánzé. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-04-q07','seed-hsk5-04',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “价值 — jiàzhí”, nghĩa là “giá trị”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-04-q08','seed-hsk5-04',8,'single_choice','Từ “改善” gần nghĩa nhất với phương án nào?','“改善” (gǎishàn) có nghĩa là “cải thiện”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 5.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-04-q09','seed-hsk5-04',9,'single_choice','Pinyin phù hợp với “建立” là phương án nào?','Pinyin của “建立” là “jiànlì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “xây dựng”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-04-q10','seed-hsk5-04',10,'single_choice','Chọn từ Hán ngữ có nghĩa “hợp lý”.','Từ phù hợp là “合理”, đọc là hélǐ. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-04-q11','seed-hsk5-04',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “资源 — zīyuán”, nghĩa là “nguồn lực”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-04-q12','seed-hsk5-04',12,'single_choice','Từ “分析” gần nghĩa nhất với phương án nào?','“分析” (fēnxī) có nghĩa là “phân tích”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 5.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-04-q13','seed-hsk5-04',13,'single_choice','Pinyin phù hợp với “措施” là phương án nào?','Pinyin của “措施” là “cuòshī”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “biện pháp”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-04-q14','seed-hsk5-04',14,'single_choice','Chọn từ Hán ngữ có nghĩa “độc lập”.','Từ phù hợp là “独立”, đọc là dúlì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
