INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk5-07','HSK5-07','HSK 5 · Đề 07','hsk','HSK 5',70,'published',1,'Đề luyện HSK 5 số 07 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk5-07-q01','seed-hsk5-07',1,'single_choice','Pinyin phù hợp với “改善” là phương án nào?','Pinyin của “改善” là “gǎishàn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cải thiện”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-07-q02','seed-hsk5-07',2,'single_choice','Chọn từ Hán ngữ có nghĩa “xây dựng”.','Từ phù hợp là “建立”, đọc là jiànlì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-07-q03','seed-hsk5-07',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “合理 — hélǐ”, nghĩa là “hợp lý”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-07-q04','seed-hsk5-07',4,'single_choice','Từ “资源” gần nghĩa nhất với phương án nào?','“资源” (zīyuán) có nghĩa là “nguồn lực”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 5.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-07-q05','seed-hsk5-07',5,'single_choice','Pinyin phù hợp với “分析” là phương án nào?','Pinyin của “分析” là “fēnxī”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “phân tích”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-07-q06','seed-hsk5-07',6,'single_choice','Chọn từ Hán ngữ có nghĩa “biện pháp”.','Từ phù hợp là “措施”, đọc là cuòshī. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-07-q07','seed-hsk5-07',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “独立 — dúlì”, nghĩa là “độc lập”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-07-q08','seed-hsk5-07',8,'single_choice','Từ “保持” gần nghĩa nhất với phương án nào?','“保持” (bǎochí) có nghĩa là “duy trì”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 5.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-07-q09','seed-hsk5-07',9,'single_choice','Pinyin phù hợp với “承担” là phương án nào?','Pinyin của “承担” là “chéngdān”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “đảm nhận”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-07-q10','seed-hsk5-07',10,'single_choice','Chọn từ Hán ngữ có nghĩa “rõ ràng”.','Từ phù hợp là “明确”, đọc là míngquè. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-07-q11','seed-hsk5-07',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “效率 — xiàolǜ”, nghĩa là “hiệu suất”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
