INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk5-08','HSK5-08','HSK 5 · Đề 08','hsk','HSK 5',70,'published',1,'Đề luyện HSK 5 số 08 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk5-08-q01','seed-hsk5-08',1,'single_choice','Pinyin phù hợp với “明确” là phương án nào?','Pinyin của “明确” là “míngquè”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “rõ ràng”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-08-q02','seed-hsk5-08',2,'single_choice','Chọn từ Hán ngữ có nghĩa “hiệu suất”.','Từ phù hợp là “效率”, đọc là xiàolǜ. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-08-q03','seed-hsk5-08',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “现象 — xiànxiàng”, nghĩa là “hiện tượng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-08-q04','seed-hsk5-08',4,'single_choice','Từ “范围” gần nghĩa nhất với phương án nào?','“范围” (fànwéi) có nghĩa là “phạm vi”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 5.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-08-q05','seed-hsk5-08',5,'single_choice','Pinyin phù hợp với “判断” là phương án nào?','Pinyin của “判断” là “pànduàn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “phán đoán”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-08-q06','seed-hsk5-08',6,'single_choice','Chọn từ Hán ngữ có nghĩa “thúc đẩy”.','Từ phù hợp là “促进”, đọc là cùjìn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-08-q07','seed-hsk5-08',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “沟通 — gōutōng”, nghĩa là “giao tiếp”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-08-q08','seed-hsk5-08',8,'single_choice','Từ “趋势” gần nghĩa nhất với phương án nào?','“趋势” (qūshì) có nghĩa là “xu hướng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 5.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-08-q09','seed-hsk5-08',9,'single_choice','Pinyin phù hợp với “观点” là phương án nào?','Pinyin của “观点” là “guāndiǎn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “quan điểm”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-08-q10','seed-hsk5-08',10,'single_choice','Chọn từ Hán ngữ có nghĩa “nguyên tắc”.','Từ phù hợp là “原则”, đọc là yuánzé. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-08-q11','seed-hsk5-08',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “价值 — jiàzhí”, nghĩa là “giá trị”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
