('seed-hsk5-09-q33','seed-hsk5-09',33,'single_choice','Pinyin phù hợp với “效率” là phương án nào?','Pinyin của “效率” là “xiàolǜ”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “hiệu suất”.',NULL,NULL,0,1,'',datetime('now')),
