INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk5-10','HSK5-10','HSK 5 · Đề 10','hsk','HSK 5',70,'published',1,'Đề luyện HSK 5 số 10 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk5-10-q01','seed-hsk5-10',1,'single_choice','Pinyin phù hợp với “保持” là phương án nào?','Pinyin của “保持” là “bǎochí”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “duy trì”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-10-q02','seed-hsk5-10',2,'single_choice','Chọn từ Hán ngữ có nghĩa “đảm nhận”.','Từ phù hợp là “承担”, đọc là chéngdān. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-10-q03','seed-hsk5-10',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “明确 — míngquè”, nghĩa là “rõ ràng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-10-q04','seed-hsk5-10',4,'single_choice','Từ “效率” gần nghĩa nhất với phương án nào?','“效率” (xiàolǜ) có nghĩa là “hiệu suất”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 5.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-10-q05','seed-hsk5-10',5,'single_choice','Pinyin phù hợp với “现象” là phương án nào?','Pinyin của “现象” là “xiànxiàng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “hiện tượng”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-10-q06','seed-hsk5-10',6,'single_choice','Chọn từ Hán ngữ có nghĩa “phạm vi”.','Từ phù hợp là “范围”, đọc là fànwéi. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-10-q07','seed-hsk5-10',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “判断 — pànduàn”, nghĩa là “phán đoán”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-10-q08','seed-hsk5-10',8,'single_choice','Từ “促进” gần nghĩa nhất với phương án nào?','“促进” (cùjìn) có nghĩa là “thúc đẩy”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 5.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-10-q09','seed-hsk5-10',9,'single_choice','Pinyin phù hợp với “沟通” là phương án nào?','Pinyin của “沟通” là “gōutōng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “giao tiếp”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-10-q10','seed-hsk5-10',10,'single_choice','Chọn từ Hán ngữ có nghĩa “xu hướng”.','Từ phù hợp là “趋势”, đọc là qūshì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-10-q11','seed-hsk5-10',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “观点 — guāndiǎn”, nghĩa là “quan điểm”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
