('seed-hsk5-10-q37','seed-hsk5-10',37,'single_choice','Pinyin phù hợp với “资源” là phương án nào?','Pinyin của “资源” là “zīyuán”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “nguồn lực”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-10-q38','seed-hsk5-10',38,'single_choice','Chọn từ Hán ngữ có nghĩa “phân tích”.','Từ phù hợp là “分析”, đọc là fēnxī. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-10-q39','seed-hsk5-10',39,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “措施 — cuòshī”, nghĩa là “biện pháp”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-10-q40','seed-hsk5-10',40,'single_choice','Từ “独立” gần nghĩa nhất với phương án nào?','“独立” (dúlì) có nghĩa là “độc lập”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 5.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-10-q41','seed-hsk5-10',41,'single_choice','Pinyin phù hợp với “保持” là phương án nào?','Pinyin của “保持” là “bǎochí”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “duy trì”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-10-q42','seed-hsk5-10',42,'single_choice','Chọn từ Hán ngữ có nghĩa “đảm nhận”.','Từ phù hợp là “承担”, đọc là chéngdān. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
