('seed-hsk5-10-q44','seed-hsk5-10',44,'single_choice','Từ “效率” gần nghĩa nhất với phương án nào?','“效率” (xiàolǜ) có nghĩa là “hiệu suất”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 5.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-10-q45','seed-hsk5-10',45,'single_choice','Pinyin phù hợp với “现象” là phương án nào?','Pinyin của “现象” là “xiànxiàng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “hiện tượng”.',NULL,NULL,0,1,'',datetime('now')),
