('seed-hsk5-11-q41','seed-hsk5-11',41,'single_choice','Pinyin phù hợp với “趋势” là phương án nào?','Pinyin của “趋势” là “qūshì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “xu hướng”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-11-q42','seed-hsk5-11',42,'single_choice','Chọn từ Hán ngữ có nghĩa “quan điểm”.','Từ phù hợp là “观点”, đọc là guāndiǎn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-11-q43','seed-hsk5-11',43,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “原则 — yuánzé”, nghĩa là “nguyên tắc”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-11-q44','seed-hsk5-11',44,'single_choice','Từ “价值” gần nghĩa nhất với phương án nào?','“价值” (jiàzhí) có nghĩa là “giá trị”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 5.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-11-q45','seed-hsk5-11',45,'single_choice','Pinyin phù hợp với “改善” là phương án nào?','Pinyin của “改善” là “gǎishàn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cải thiện”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-11-q46','seed-hsk5-11',46,'single_choice','Chọn từ Hán ngữ có nghĩa “xây dựng”.','Từ phù hợp là “建立”, đọc là jiànlì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-11-q47','seed-hsk5-11',47,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “合理 — hélǐ”, nghĩa là “hợp lý”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-11-q48','seed-hsk5-11',48,'single_choice','Từ “资源” gần nghĩa nhất với phương án nào?','“资源” (zīyuán) có nghĩa là “nguồn lực”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 5.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-11-q49','seed-hsk5-11',49,'single_choice','Pinyin phù hợp với “分析” là phương án nào?','Pinyin của “分析” là “fēnxī”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “phân tích”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-11-q50','seed-hsk5-11',50,'single_choice','Chọn từ Hán ngữ có nghĩa “biện pháp”.','Từ phù hợp là “措施”, đọc là cuòshī. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now'));
