('seed-hsk5-12-q45','seed-hsk5-12',45,'single_choice','Pinyin phù hợp với “明确” là phương án nào?','Pinyin của “明确” là “míngquè”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “rõ ràng”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-12-q46','seed-hsk5-12',46,'single_choice','Chọn từ Hán ngữ có nghĩa “hiệu suất”.','Từ phù hợp là “效率”, đọc là xiàolǜ. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-12-q47','seed-hsk5-12',47,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “现象 — xiànxiàng”, nghĩa là “hiện tượng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-12-q48','seed-hsk5-12',48,'single_choice','Từ “范围” gần nghĩa nhất với phương án nào?','“范围” (fànwéi) có nghĩa là “phạm vi”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 5.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-12-q49','seed-hsk5-12',49,'single_choice','Pinyin phù hợp với “判断” là phương án nào?','Pinyin của “判断” là “pànduàn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “phán đoán”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-12-q50','seed-hsk5-12',50,'single_choice','Chọn từ Hán ngữ có nghĩa “thúc đẩy”.','Từ phù hợp là “促进”, đọc là cùjìn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now'));
