INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk5-13','HSK5-13','HSK 5 · Đề 13','hsk','HSK 5',70,'published',1,'Đề luyện HSK 5 số 13 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk5-13-q01','seed-hsk5-13',1,'single_choice','Pinyin phù hợp với “促进” là phương án nào?','Pinyin của “促进” là “cùjìn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “thúc đẩy”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-13-q02','seed-hsk5-13',2,'single_choice','Chọn từ Hán ngữ có nghĩa “giao tiếp”.','Từ phù hợp là “沟通”, đọc là gōutōng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-13-q03','seed-hsk5-13',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “趋势 — qūshì”, nghĩa là “xu hướng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-13-q04','seed-hsk5-13',4,'single_choice','Từ “观点” gần nghĩa nhất với phương án nào?','“观点” (guāndiǎn) có nghĩa là “quan điểm”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 5.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-13-q05','seed-hsk5-13',5,'single_choice','Pinyin phù hợp với “原则” là phương án nào?','Pinyin của “原则” là “yuánzé”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “nguyên tắc”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-13-q06','seed-hsk5-13',6,'single_choice','Chọn từ Hán ngữ có nghĩa “giá trị”.','Từ phù hợp là “价值”, đọc là jiàzhí. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-13-q07','seed-hsk5-13',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “改善 — gǎishàn”, nghĩa là “cải thiện”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-13-q08','seed-hsk5-13',8,'single_choice','Từ “建立” gần nghĩa nhất với phương án nào?','“建立” (jiànlì) có nghĩa là “xây dựng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 5.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-13-q09','seed-hsk5-13',9,'single_choice','Pinyin phù hợp với “合理” là phương án nào?','Pinyin của “合理” là “hélǐ”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “hợp lý”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-13-q10','seed-hsk5-13',10,'single_choice','Chọn từ Hán ngữ có nghĩa “nguồn lực”.','Từ phù hợp là “资源”, đọc là zīyuán. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-13-q11','seed-hsk5-13',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “分析 — fēnxī”, nghĩa là “phân tích”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-13-q12','seed-hsk5-13',12,'single_choice','Từ “措施” gần nghĩa nhất với phương án nào?','“措施” (cuòshī) có nghĩa là “biện pháp”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 5.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-13-q13','seed-hsk5-13',13,'single_choice','Pinyin phù hợp với “独立” là phương án nào?','Pinyin của “独立” là “dúlì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “độc lập”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-13-q14','seed-hsk5-13',14,'single_choice','Chọn từ Hán ngữ có nghĩa “duy trì”.','Từ phù hợp là “保持”, đọc là bǎochí. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-13-q15','seed-hsk5-13',15,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “承担 — chéngdān”, nghĩa là “đảm nhận”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-13-q16','seed-hsk5-13',16,'single_choice','Từ “明确” gần nghĩa nhất với phương án nào?','“明确” (míngquè) có nghĩa là “rõ ràng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 5.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-13-q17','seed-hsk5-13',17,'single_choice','Pinyin phù hợp với “效率” là phương án nào?','Pinyin của “效率” là “xiàolǜ”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “hiệu suất”.',NULL,NULL,0,1,'',datetime('now')),
