('seed-hsk5-13-q49','seed-hsk5-13',49,'single_choice','Pinyin phù hợp với “合理” là phương án nào?','Pinyin của “合理” là “hélǐ”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “hợp lý”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-13-q50','seed-hsk5-13',50,'single_choice','Chọn từ Hán ngữ có nghĩa “nguồn lực”.','Từ phù hợp là “资源”, đọc là zīyuán. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now'));
