('seed-hsk5-16-q09','seed-hsk5-16',9,'single_choice','Pinyin phù hợp với “明确” là phương án nào?','Pinyin của “明确” là “míngquè”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “rõ ràng”.',NULL,NULL,0,1,'',datetime('now')),
