INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk5-18','HSK5-18','HSK 5 · Đề 18','hsk','HSK 5',70,'published',1,'Đề luyện HSK 5 số 18 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk5-18-q01','seed-hsk5-18',1,'single_choice','Pinyin phù hợp với “价值” là phương án nào?','Pinyin của “价值” là “jiàzhí”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “giá trị”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-18-q02','seed-hsk5-18',2,'single_choice','Chọn từ Hán ngữ có nghĩa “cải thiện”.','Từ phù hợp là “改善”, đọc là gǎishàn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-18-q03','seed-hsk5-18',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “建立 — jiànlì”, nghĩa là “xây dựng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-18-q04','seed-hsk5-18',4,'single_choice','Từ “合理” gần nghĩa nhất với phương án nào?','“合理” (hélǐ) có nghĩa là “hợp lý”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 5.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-18-q05','seed-hsk5-18',5,'single_choice','Pinyin phù hợp với “资源” là phương án nào?','Pinyin của “资源” là “zīyuán”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “nguồn lực”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-18-q06','seed-hsk5-18',6,'single_choice','Chọn từ Hán ngữ có nghĩa “phân tích”.','Từ phù hợp là “分析”, đọc là fēnxī. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-18-q07','seed-hsk5-18',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “措施 — cuòshī”, nghĩa là “biện pháp”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-18-q08','seed-hsk5-18',8,'single_choice','Từ “独立” gần nghĩa nhất với phương án nào?','“独立” (dúlì) có nghĩa là “độc lập”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 5.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-18-q09','seed-hsk5-18',9,'single_choice','Pinyin phù hợp với “保持” là phương án nào?','Pinyin của “保持” là “bǎochí”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “duy trì”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-18-q10','seed-hsk5-18',10,'single_choice','Chọn từ Hán ngữ có nghĩa “đảm nhận”.','Từ phù hợp là “承担”, đọc là chéngdān. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-18-q11','seed-hsk5-18',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “明确 — míngquè”, nghĩa là “rõ ràng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-18-q12','seed-hsk5-18',12,'single_choice','Từ “效率” gần nghĩa nhất với phương án nào?','“效率” (xiàolǜ) có nghĩa là “hiệu suất”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 5.',NULL,NULL,0,1,'',datetime('now')),
