INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk5-19','HSK5-19','HSK 5 · Đề 19','hsk','HSK 5',70,'published',1,'Đề luyện HSK 5 số 19 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk5-19-q01','seed-hsk5-19',1,'single_choice','Pinyin phù hợp với “承担” là phương án nào?','Pinyin của “承担” là “chéngdān”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “đảm nhận”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-19-q02','seed-hsk5-19',2,'single_choice','Chọn từ Hán ngữ có nghĩa “rõ ràng”.','Từ phù hợp là “明确”, đọc là míngquè. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-19-q03','seed-hsk5-19',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “效率 — xiàolǜ”, nghĩa là “hiệu suất”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-19-q04','seed-hsk5-19',4,'single_choice','Từ “现象” gần nghĩa nhất với phương án nào?','“现象” (xiànxiàng) có nghĩa là “hiện tượng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 5.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-19-q05','seed-hsk5-19',5,'single_choice','Pinyin phù hợp với “范围” là phương án nào?','Pinyin của “范围” là “fànwéi”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “phạm vi”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-19-q06','seed-hsk5-19',6,'single_choice','Chọn từ Hán ngữ có nghĩa “phán đoán”.','Từ phù hợp là “判断”, đọc là pànduàn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-19-q07','seed-hsk5-19',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “促进 — cùjìn”, nghĩa là “thúc đẩy”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-19-q08','seed-hsk5-19',8,'single_choice','Từ “沟通” gần nghĩa nhất với phương án nào?','“沟通” (gōutōng) có nghĩa là “giao tiếp”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 5.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-19-q09','seed-hsk5-19',9,'single_choice','Pinyin phù hợp với “趋势” là phương án nào?','Pinyin của “趋势” là “qūshì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “xu hướng”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-19-q10','seed-hsk5-19',10,'single_choice','Chọn từ Hán ngữ có nghĩa “quan điểm”.','Từ phù hợp là “观点”, đọc là guāndiǎn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-19-q11','seed-hsk5-19',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “原则 — yuánzé”, nghĩa là “nguyên tắc”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-19-q12','seed-hsk5-19',12,'single_choice','Từ “价值” gần nghĩa nhất với phương án nào?','“价值” (jiàzhí) có nghĩa là “giá trị”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 5.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-19-q13','seed-hsk5-19',13,'single_choice','Pinyin phù hợp với “改善” là phương án nào?','Pinyin của “改善” là “gǎishàn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cải thiện”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-19-q14','seed-hsk5-19',14,'single_choice','Chọn từ Hán ngữ có nghĩa “xây dựng”.','Từ phù hợp là “建立”, đọc là jiànlì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-19-q15','seed-hsk5-19',15,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “合理 — hélǐ”, nghĩa là “hợp lý”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-19-q16','seed-hsk5-19',16,'single_choice','Từ “资源” gần nghĩa nhất với phương án nào?','“资源” (zīyuán) có nghĩa là “nguồn lực”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 5.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-19-q17','seed-hsk5-19',17,'single_choice','Pinyin phù hợp với “分析” là phương án nào?','Pinyin của “分析” là “fēnxī”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “phân tích”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-19-q18','seed-hsk5-19',18,'single_choice','Chọn từ Hán ngữ có nghĩa “biện pháp”.','Từ phù hợp là “措施”, đọc là cuòshī. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-19-q19','seed-hsk5-19',19,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “独立 — dúlì”, nghĩa là “độc lập”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
