('seed-hsk5-20-q21','seed-hsk5-20',21,'single_choice','Pinyin phù hợp với “观点” là phương án nào?','Pinyin của “观点” là “guāndiǎn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “quan điểm”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk5-20-q22','seed-hsk5-20',22,'single_choice','Chọn từ Hán ngữ có nghĩa “nguyên tắc”.','Từ phù hợp là “原则”, đọc là yuánzé. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
